import {RELATIONSHIP_OPENINGS} from './conversation-opening.mjs';
// New conversations have five stage choices. Legacy variants remain read-only
// compatibility in the opening normalizer, never generated by this form.
export function mountOpeningPicker(fields,{special=false,getStage=()=>({})}={}){
 const hint=fields.querySelector('[data-opening-hint]'),input=fields.querySelector('[name="stage"]'),group=fields.querySelector('[data-opening-group="stage"]');
 const controls=RELATIONSHIP_OPENINGS.map((p,index)=>{
  const b=document.createElement('button');b.type='button';b.dataset.openingChoice=p.id;b.setAttribute('role','radio');
  b.onclick=()=>{input.value=p.id;const content=getStage(p.id);for(const key of ['prehistory','toneReminder']){const field=fields.querySelector('[name="'+key+'"]');if(field)field.value=content[key]||'';}controls.forEach(c=>{c.setAttribute('aria-checked',String(c===b));c.tabIndex=c===b?0:-1;});fields.closest('form').querySelector('[role=status]').textContent='';hint.textContent='虚构故事起点，可以修改前情与基调。只影响这段新对话。';};
  b.onkeydown=e=>{let next;if(e.key==='ArrowRight'||e.key==='ArrowDown')next=(index+1)%5;else if(e.key==='ArrowLeft'||e.key==='ArrowUp')next=(index+4)%5;else if(e.key==='Home')next=0;else if(e.key==='End')next=4;else return;e.preventDefault();controls[next].focus();controls[next].click();};group.append(b);return b;
 });
 return {reset(){input.value='';controls.forEach((b,i)=>{const data=getStage(RELATIONSHIP_OPENINGS[i].id);b.textContent=data.label||['初来此刻','日常展开','共同默契','亲近相处','心意明朗'][i];b.title=data.prehistory||'选择可编辑故事起点';b.setAttribute('aria-checked','false');b.tabIndex=i===0?0:-1;});hint.textContent='请选择故事进度，之后自然发展。';},validate(){if(!input.value){controls[0].focus();throw Error('请选择故事进度。');}}};
}
